  {
   "tipo": "script_godot",
   "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Il nodo Player deve essere presente"):
		return

	player._time_since_last_shot = 1.0
	await tap_action("shoot")
	await wait_physics_frames(2)

	var player_bullets := player.get_children().filter(func(c): return c.name.begins_with("Bullet"))
	check("not_child_of_player", player_bullets.size() == 0, "I proiettili NON devono essere aggiunti come nodi figli del Player")

	var main_bullets := main.get_children().filter(func(c): return c.name.begins_with("Bullet"))
	check("child_of_main", main_bullets.size() > 0, "I proiettili devono essere aggiunti direttamente alla scena principale")

	await wait_physics_frames(2)
	var bullet_count_1 := main.get_children().filter(func(c): return c.name.begins_with("Bullet")).size()
	await wait_physics_frames(5)
	var bullet_count_2 := main.get_children().filter(func(c): return c.name.begins_with("Bullet")).size()
	check("cooldown_works", bullet_count_1 == bullet_count_2, "Il proiettile non deve essere sparato a ogni singolo fotogramma durante il cooldown")
",
